function render() {
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    // Clear canvas
    ctx.fillStyle = '#0f1320';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // Draw hazards
    ctx.fillStyle = '#ff5555';
    for (const h of hazards) {
      ctx.beginPath();
      ctx.arc(h.x, h.y, h.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // Draw player (high contrast)
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
    ctx.fill();
    // HUD: score
    ctx.fillStyle = '#e6e6f0';
    ctx.font = '16px ui-sans-serif, system-ui';
    ctx.textAlign = 'left';
    ctx.fillText('Score ' + score, 12, 22);
    // If game over, overlay message
    if (phase === 'gameover') {
      ctx.fillStyle = 'rgba(10,10,15,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff5555';
      ctx.textAlign = 'center';
      ctx.font = '44px ui-sans-serif, system-ui';
      ctx.fillText('Game Over', canvas.width/2, canvas.height/2 - 30);
      ctx.fillStyle = '#e6e6f0';
      ctx.font = '20px ui-sans-serif, system-ui';
      ctx.fillText('Final score ' + score, canvas.width/2, canvas.height/2 + 4);
      ctx.fillText('Press R or click Restart', canvas.width/2, canvas.height/2 + 30);
    }
  }

  // === OBSERVABLE CONTRACT ===============================================
  function publishState() {
    const canvas = document.getElementById('game');
    const visible = player.x >= 0 && player.x <= canvas.width && player.y >= 0 && player.y <= canvas.height;
    window.__game = {
      state: phase === 'playing' ? 'playing' : 'gameover',
      score,
      player: { x: player.x, y: player.y, visible },
      objective: 'Flip direction to bounce between walls and avoid hazards.'
    };
  }

